from pathlib import Path
import html,re,difflib
import markdown
OUT=Path(__file__).resolve().parent;ROOT=OUT.parents[3]
def render(s,prefix):
 s=re.sub(r'<!--\s*@[^>]*-->','',s)
 return markdown.markdown(s,extensions=['extra','sane_lists']).replace('id="fn','id="'+prefix+'-fn').replace('href="#fn','href="#'+prefix+'-fn')
def photo(name,caption):
 return '<figure><a href="'+name+'.png"><img src="'+name+'.png" alt="'+html.escape(caption,quote=True)+'"></a><figcaption>'+caption+'</figcaption></figure>'
before=(OUT/'Trans_Pit.before.md').read_text(encoding='utf-8');after=(OUT/'Trans_Pit.after.md').read_text(encoding='utf-8');assert after==(ROOT/'commons/maps/Trans_Pit/final.md').read_text(encoding='utf-8')
a,b=before.split('\n\n'),after.split('\n\n');pairs=[]
for i,(tag,x,y,u,v) in enumerate(difflib.SequenceMatcher(None,a,b,autojunk=False).get_opcodes()):
 if tag=='equal':continue
 left=render('\n\n'.join(a[x:y]),'old-'+str(i)) or '<p>New illustration.</p>';right=render('\n\n'.join(b[u:v]),'new-'+str(i)) or '<p>Passage removed.</p>'
 pairs.append('<div class="pair"><div><h4>Before</h4>'+left+'</div><div><h4>Now</h4>'+right+'</div></div>')
css=re.search(r'<style>(.*?)</style>',(OUT.parent/'2026-09-23-transformation-encounters/index.html').read_text(encoding='utf-8'),re.S)[1]
css+=' .pair img{max-width:100%} .reading{margin-top:25px} figure img{height:auto} .raw{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.raw figure{margin:0}.raw figcaption{font-size:14px}@media(max-width:850px){.raw{grid-template-columns:1fr}}'
page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>The Moving Boundary — make room</title><style>'+css+'</style></head><body><main>'
page+='''<div class="eyebrow">Ada Research / Transformation / 23 September 2026</div><h1>The Moving Boundary</h1><div class="intro"><p>Standing still does not hold the room still.</p><p>A cube keeps time. A door waits for an arrival.</p></div><p class="status">Applied to <strong>Trans_Pit/final.md</strong>. Two short prose changes and two native museum figures. The existing artifacts and chapter ending remain.</p><nav><a href="#encounter">Shared illustrations</a><a href="#comparison">Text differences</a><a href="#reading">Read the hall</a><a href="#evidence">Evidence</a><a href="/compose/sources?map=Trans_Pit&amp;doc=final">Comment on final.md</a></nav>'''
page+='<section id="encounter"><h2>The room changes around the view</h2>'+photo('the-room-keeps-time','One lane at the small and large extremes. The same camera sees the doorway beyond the little cube, then loses it behind the enlarged cube. The clock continues without an approaching visitor.')+'<h2>Make room</h2>'+photo('make-room','The current museum door: closed, during its turn, and fully open. Its leaves move sideways and up, turn, then shrink into recesses. The opening appears before the full movement finishes. The frame stays still.')+'<p>The previous room responds to the approaching body. The timed studies continue without it. This final door brings the body back as an input: the same operations make a welcome.</p></section>'
page+='<section id="comparison"><h2>Keep the encounter, clarify the relation</h2><p>The opening, four code excerpts and closing welcome remain. The clock paragraph gains one concrete consequence; the door waits for arrival. The technical companion now describes the current level-floor museum and final airlock, with the obsolete version preserved.</p><details open><summary>Original and revised passages</summary>'+''.join(pairs)+'</details><p><a href="Trans_Pit.diff">Exact manuscript diff</a> · <a href="source-changes.diff">Companion and intent changes</a></p></section>'
page+='<section id="reading"><h2>The Moving Boundary</h2><article class="reading">'+render(after,'reading')+'</article></section>'
page+='''<section id="evidence"><h2>What was checked</h2><p>46 focused checks pass in the actual isolated museum. The ordinary grower clock continues with the visitor parked away. Supplied walking input takes the normal museum body to the door, through it and back. It opens, holds while the body waits, then closes after vacancy and its delay.</p><p>Figure poses are selected and frozen for comparison. The runtime controller is restored for the door interaction. These checks do not claim a full hall traversal, headset use or learner understanding.</p><details><summary>Original native door captures</summary><div class="raw">'''+photo('door-closed','Opening fraction 0.')+photo('door-turning','Opening fraction 0.52.')+photo('door-open','Opening fraction 1.')+'''</div></details><p><a href="report.json">Runtime checks</a> · <a href="source_manifest.json">Runtime inputs</a> · <a href="verification.json">Publication checks</a> · <a href="SUMMARY.md">Decisions and scope</a></p></section><footer><p>Next: Array. The cube we met at the start of Transformation gains company, and each position gains an address.</p></footer></main></body></html>'''
(OUT/'index.html').write_text(page,encoding='utf-8');print(OUT/'index.html')
